<script lang="ts">
 import {page} from '$app/state';import {invalidateAll} from '$app/navigation';
 let pending=$state(false),message=$state('');
 $effect(()=>{const language=page.data.lang;document.documentElement.lang=language;navigator.serviceWorker?.ready.then(registration=>registration.active?.postMessage({type:'rose-language',language})).catch(()=>{});});
 async function change(event:Event){const select=event.currentTarget as HTMLSelectElement,language=select.value;pending=true;message='';try{const response=await fetch('/api/language',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language})});if(!response.ok)throw new Error();await invalidateAll();document.documentElement.lang=language;}catch{message=page.data.lang==='fr'?'La langue n’a pas pu être changée. Réessaie.':'Language could not be changed. Please try again.';select.value=page.data.lang;}finally{pending=false;}}
</script>
<div class="language-switch"><label for="app-language">{page.data.lang==='fr'?'Langue':'Language'}</label><select id="app-language" value={page.data.lang} onchange={change} disabled={pending} aria-label={page.data.lang==='fr'?'Choisir la langue':'Choose language'}><option value="en" lang="en">EN</option><option value="fr" lang="fr">FR</option></select>{#if message}<span role="alert">{message}</span>{/if}</div>
<style>.language-switch{display:flex;align-items:center;position:relative}.language-switch label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}select{font-family:inherit;font-size:13px;font-weight:600;color:#8f3155;background:#fff8fb;border:1px solid #e5c8d3;border-radius:14px;padding:9px 7px;min-height:44px;cursor:pointer}select:focus-visible{outline:2px solid #a92354;outline-offset:3px}.language-switch span{position:absolute;top:100%;right:0;width:220px;background:white;padding:12px;z-index:20;border-radius:12px;font-size:13px}</style>
